#!/usr/bin/env bash
# Generate Python gRPC stubs from trading_analysis.proto.
# Pinned tools: see extensions/python/requirements-grpc.txt
#   grpcio==1.68.1  grpcio-tools==1.68.1  protobuf==5.29.3
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/python/ats_research/generated"
PROTO="$ROOT/proto/trading_analysis.proto"
mkdir -p "$OUT"
touch "$OUT/__init__.py"

python3 -m grpc_tools.protoc \
  -I"$ROOT/proto" \
  --python_out="$OUT" \
  --grpc_python_out="$OUT" \
  "$PROTO"

# Fix absolute import generated by grpc_tools for package-relative use.
sed -i 's/^import trading_analysis_pb2/from . import trading_analysis_pb2/' \
  "$OUT/trading_analysis_pb2_grpc.py"

echo "GEN_OK out=$OUT tools=grpcio-tools==1.68.1"
